class Solution {
public:
    bool checkPalindromeFormation(string a, string b) {
        int n = a.size();
        auto isPal = [](const string& s) {
            for (int i = 0, j = s.size() - 1; i < j; ++i, --j)
                if (s[i] != s[j]) return false;
            return true;
        };
        for (int i = 0; i <= n; ++i) {
            if (isPal(a.substr(0, i) + b.substr(i))) return true;
            if (isPal(b.substr(0, i) + a.substr(i))) return true;
        }
        return false;
    }
};

