class Solution {
    public boolean checkPalindromeFormation(String a, String b) {
        int n = a.length();
        for (int i = 0; i <= n; i++) {
            StringBuilder x = new StringBuilder(a.substring(0, i)).append(b.substring(i));
            StringBuilder y = new StringBuilder(b.substring(0, i)).append(a.substring(i));
            if (isPal(x) || isPal(y)) return true;
        }
        return false;
    }

    private boolean isPal(StringBuilder s) {
        for (int i = 0, j = s.length() - 1; i < j; i++, j--)
            if (s.charAt(i) != s.charAt(j)) return false;
        return true;
    }
}

